  function productForm(product = null) {const specs = [{name: "sku", label: "商品编号（SKU，唯一）", required: true}, {name: "name", label: "商品名称", required: true}, {name: "category", label: "分类", required: true}, {name: "brand", label: "品牌"}, {name: "specification", label: "规格"}, {name: "price_yuan", label: "单价（元）", type: "number", required: true, min: 0, max: 9999999, step: 0.01, value: 0}, {name: "unit", label: "单位", value: "件", required: true}, {name: "source_type", label: "来源类型", options: {self_operated: "自营", third_party: "合作第三方"}}, {name: "description", label: "商品说明", type: "textarea"}, {name: "is_active", label: "立即上架", type: "checkbox"}]; formModal(product ? "编辑商品" : "新建商品", specs, values => {const {price_yuan, ...params} = values; return api(product ? "commerce.update_product" : "commerce.create_product", {...params, price_cents: Math.round(price_yuan * 100), ...(product ? {product_id: product.id} : {})});}, {values: product ? {...product, price_yuan: product.price_cents / 100} : {}, note: "仅建立模拟商品资料。请勿填写治愈保证、诊疗结论或恐吓购买话术。"});}
