  async function ordersPage(host) {heading(host, "模拟订单", "仅用于本地流程验证，没有真实资金或物流"); const orders = await api("commerce.list_orders"); host.append(notice("本页所有“支付”“送达”都是模拟状态。", "warning"), orders.length ? orders.map(order => itemCard(order.product_name || order.product_name_snapshot || "商品订单", `${order.order_no || "订单 " + order.id} · ${time(order.created_at)}`, facts(order, {omit: ["id", "product_name", "product_name_snapshot", "order_no", "created_at", "status"]}), state.user.role_code === "operator" && order.status === "created" ? [btn("标记模拟送达", async () => {await api("commerce.mark_order_delivered", {order_id: order.id}); await render();}, "soft small")] : state.user.role_code === "member" ? [btn("再次模拟购买", () => confirmAction("再次模拟购买？", "将按商品当前上架状态和当前价格生成一个新模拟订单，不会发生真实支付。", async () => {await api("commerce.reorder", {order_id: order.id}); await render();}), "small")] : [], status(order.status))) : empty("模拟购买后，订单会出现在这里。"));}
  async function importBackup() {confirmAction("导入完整数据备份", "请选择本应用导出的 ZIP 备份。导入会覆盖本机全部账号、聊天、生活和服务数据，不会合并；系统将先保存一份旧数据安全备份。导入后需要用备份内账号重新登录。建议先自行导出当前完整备份并妥善保管。", async () => {const result = await api("native.importBackup", {confirm: true}); if (result?.cancelled) return; state.user = null; state.provider = null; await refreshAuth(); toast("导入完成，请使用备份里的账号登录");}, true);}
